ServerLang = {}

local ServerLangItems = T(Global, "ServerLangItems")

function ServerLang:init()
    WebService:GetGameServerLang(function(data)
        if not data then
            return
        end
        TableUtil.mergeTable(ServerLangItems, data)
    end)
end

function ServerLang:getString(key, lang)
    local item = ServerLangItems[key]
    if not item then
        return key
    end
    return item[lang] or item["en"] or key
end

function ServerLang:format(key, lang, ...)
    return string.format(self:getString(key, lang), ...)
end

return ServerLang